export function standaloneMode(nav,media){return !!nav?.standalone||!!media('(display-mode: standalone)').matches;}
export function playViewportHeight({playing,standalone,visualHeight,stableHeight}){return Math.max(1,playing&&!standalone&&stableHeight>0?stableHeight:visualHeight);}
export function mountPhoneShell({win,doc,nav,media,storage,canUpdate,onHide}){const $=id=>doc.getElementById(id);const standalone=standaloneMode(nav,media);let pendingInstall=null,registration=null;
 doc.body.classList.toggle('installed-app',standalone);$('install-app').hidden=standalone;$('app-install-banner').hidden=standalone||!(nav.maxTouchPoints>0);$('app-mode').textContent=standalone?'HOME-SCREEN APP':'BROWSER MODE';
 const close=()=>{$('install-panel').hidden=true;};$('install-app').onclick=$('install-banner-action').onclick=async()=>{if(pendingInstall){await pendingInstall.prompt();pendingInstall=null;return;}$('install-panel').hidden=false;$('install-close').focus?.();};$('install-close').onclick=close;
 const setOnline=()=>{const online=nav.onLine!==false;doc.body.classList.toggle('offline',!online);$('offline-status').hidden=online;for(const id of ['room-create','room-join']){const b=$(id);if(!online){b.dataset.offline='true';b.disabled=true;}else if(b.dataset.offline==='true'){b.disabled=false;delete b.dataset.offline;}}};setOnline();win.addEventListener('online',setOnline);win.addEventListener('offline',setOnline);
 win.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pendingInstall=e;});win.addEventListener('appinstalled',()=>{$('install-app').hidden=true;$('app-install-banner').hidden=true;close();});win.addEventListener('pagehide',onHide);
 $('apply-update').onclick=()=>{if(!canUpdate()){$('update-note').textContent='Finish your match or return to the lobby before updating.';return;}registration?.waiting?.postMessage({type:'ACTIVATE_UPDATE'});};
 let applying=false;const checkUpdate=()=>{if(registration?.waiting){$('app-update').hidden=false;$('apply-update').onclick=()=>{if(!canUpdate()){$('update-note').textContent='Return to the lobby first. Your match will not be interrupted.';return;}applying=true;registration.waiting.postMessage({type:'ACTIVATE_UPDATE'});};}};
 if(nav.serviceWorker){nav.serviceWorker.addEventListener('controllerchange',()=>{if(applying)win.location.reload();});nav.serviceWorker.register('/service-worker.js',{scope:'/',updateViaCache:'none'}).then(r=>{registration=r;checkUpdate();r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&nav.serviceWorker.controller)checkUpdate();});});}).catch(()=>{});}
 const read=()=>{try{return storage?.getItem('stickman-intro-seen')==='yes';}catch{return false;}};
 return {standalone,seenIntro:read(),markIntroduced(){try{storage?.setItem('stickman-intro-seen','yes');}catch{}},close};}
